import type { ExpansionSpec } from './types';
const refs = {
 sleep: ['CDC: Providing care for babies to sleep safely', 'https://www.cdc.gov/sudden-infant-death/sleep-safely/'],
 newborn: ['NHLBI: Newborn breathing conditions, types', 'https://www.nhlbi.nih.gov/health/newborn-breathing-conditions/types'],
 urine: ['NIDDK: Urinary tract infections in children', 'https://www.niddk.nih.gov/health-information/urologic-diseases/urinary-tract-infections-in-children'],
 ethics: ['WMA International Code of Medical Ethics', 'https://www.wma.net/policies-post/wma-international-code-of-medical-ethics/'],
 bv: ['CDC: Bacterial vaginosis diagnostic guidance', 'https://www.cdc.gov/std/treatment-guidelines/BV.htm'],
 candida: ['CDC: Vulvovaginal candidiasis', 'https://www.cdc.gov/std/treatment-guidelines/candidiasis.htm'],
 trichomonas: ['CDC: Trichomoniasis', 'https://www.cdc.gov/std/treatment-guidelines/trichomoniasis.htm'],
 labor: ['ACOG: Preterm labor and birth', 'https://www.acog.org/womens-health/faqs/preterm-labor-and-birth'],
 skin: ['ACOG: Skin conditions during pregnancy', 'https://www.acog.org/womens-health/faqs/skin-conditions-during-pregnancy'],
 thyroid: ['NIDDK: Thyroid disease and pregnancy', 'https://www.niddk.nih.gov/health-information/endocrine-diseases/pregnancy-thyroid-disease'],
 perinatal: ['NIMH: Perinatal depression and postpartum psychosis', 'https://www.nimh.nih.gov/health/publications/perinatal-depression'],
 ocd: ['NIMH: Obsessive-compulsive disorder', 'https://www.nimh.nih.gov/health/publications/obsessive-compulsive-disorder-when-unwanted-thoughts-or-repetitive-behaviors-take-over'],
 bipolar: ['NIMH: Bipolar disorder', 'https://www.nimh.nih.gov/health/publications/bipolar-disorder'],
 eating: ['NIH: Eating disorders', 'https://health.nih.gov/health-topics-a-z/eating-disorders'],
 pediatric: ['WHO Pocket Book of Hospital Care for Children, 2nd edition (2013)', 'https://www.who.int/publications/i/item/978-92-4-154837-3'],
 antibiotic: ['CDC: Pediatric outpatient clinical care', 'https://www.cdc.gov/antibiotic-use/hcp/clinical-care/pediatric-outpatient.html'],
 heart: ['NHLBI: Congenital heart defects, types', 'https://www.nhlbi.nih.gov/health/congenital-heart-defects/types'],
 pregnancy: ['ACOG: Bleeding during pregnancy', 'https://www.acog.org/womens-health/faqs/bleeding-during-pregnancy'],
 hypertension: ['ACOG: Preeclampsia and high blood pressure during pregnancy', 'https://www.acog.org/womens-health/faqs/preeclampsia-and-high-blood-pressure-during-pregnancy'],
 loss: ['ACOG: Early pregnancy loss', 'https://www.acog.org/womens-health/faqs/early-pregnancy-loss'],
 bleeding: ['ACOG: Abnormal uterine bleeding', 'https://www.acog.org/womens-health/faqs/abnormal-uterine-bleeding'],
 ectopic: ['ACOG: Ectopic pregnancy', 'https://www.acog.org/womens-health/faqs/ectopic-pregnancy'],
 clinical: ['Clinical Methods, 3rd edition: examination and diagnostic reasoning (1990)', 'https://www.ncbi.nlm.nih.gov/books/NBK201/'],
 appendicitis: ['NIDDK: Appendicitis', 'https://www.niddk.nih.gov/health-information/digestive-diseases/appendicitis'],
 intussusception: ['NIDDK: Intussusception', 'https://www.niddk.nih.gov/health-information/digestive-diseases/anatomic-problems-lower-gi-tract/intussusception'],
} satisfies Record<string, [string,string]>;
type Ref = keyof typeof refs;
let serial = 600;
function q(subject: string, system: string, topic: string, stem: string, answer: string, explanation: string, wrong: [string,string][], objective: string, ref: Ref = 'clinical', reasoning: 'application'|'integration'|'prioritization' = 'integration'): ExpansionSpec {
 const nearest = subject === 'Pediatrics' ? 'Batch 08 pediatric dehydration, croup localization, coarctation, pyloric acid-base change and intussusception mechanism' : subject === 'Obstetrics' ? 'Batch 08 ectopic site, previa identification, abruption mechanism, preeclampsia mechanism and uterine atony mechanism' : subject === 'Ethics' || subject === 'Psychiatry' ? 'Batch 06 consent, capacity, confidentiality, surrogate, interpreter, disclosure and voluntariness objectives; no psychiatric diagnostic item appears there' : 'Batch 08 surgical recognition and mechanism items, including obstruction, ischemia, hernia and fracture vascular risk';
 return {code: `op26x-${String(++serial).padStart(4,'0')}`, concept: topic.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,''), reasoning, difficultyReason: `${reasoning === 'prioritization' ? 'Prioritize the stated action with the clinical constraints' : reasoning === 'application' ? 'Apply the stated disease principle to the vignette' : 'Combine the independent clinical findings to distinguish alternatives'}: ${objective}`, evidenceNote: `${refs[ref][0]}: publisher/official indexed record checked 2026-10-29. Supports disease framework or clinical examination; book-level references do not independently validate every option. Older books are not used to assert a current drug regimen.`, semanticReviewNote: `Compared with ${nearest}; distinct objective: ${objective}`, concerns: [], question: {subject,system,topic,stem,options:[[answer,explanation],...wrong],explanation,objective,reference:refs[ref],exam:'Step 2 CK',difficulty:{application:2,integration:3,prioritization:4}[reasoning]}};
}
export const specs: ExpansionSpec[] = [
q('Pediatrics','Respiratory','Neonatal respiratory distress surfactant','A 28-week premature infant develops grunting and retractions soon after birth. Radiography shows low lung volumes with diffuse granular opacities and air bronchograms. Which deficiency best explains the poor compliance?', 'Pulmonary surfactant deficiency', 'Immature type II pneumocytes may supply inadequate surfactant, increasing alveolar surface tension and promoting collapse. Prematurity, early distress and low-volume granular lungs support neonatal respiratory distress syndrome rather than retained fluid in an otherwise mature lung.', [['Excess alveolar surfactant secretion','Surfactant lowers surface tension and would not explain deficiency-related collapse.'],['Isolated upper-airway mucus obstruction','A proximal mucus plug does not explain the diffuse low-volume alveolar pattern.'],['An excess of circulating fetal hemoglobin','Hemoglobin composition does not cause the primary compliance defect.']], 'Link prematurity and diffuse low-volume lungs to surfactant-dependent alveolar instability.','newborn'),
q('Pediatrics','Respiratory','Transient tachypnea retained fetal fluid','A term newborn delivered by elective cesarean without labor has tachypnea shortly after birth. Radiography shows hyperinflation and fluid in interlobar fissures; symptoms improve over the next day. Which mechanism is most likely?', 'Delayed clearance of fetal lung fluid', 'Transient tachypnea results from delayed absorption of fetal pulmonary fluid and is associated with cesarean delivery without labor. A rapidly improving course with fissural fluid differs from severe surfactant deficiency in a very premature infant.', [['Complete absence of both lungs','Pulmonary agenesis would not produce this mild improving bilateral fluid pattern.'],['Progressive destruction of alveoli from emphysema','The neonatal onset and rapid improvement do not fit chronic alveolar destruction.'],['Congenital absence of respiratory drive','The infant is tachypneic rather than failing to initiate breaths.']], 'Combine delivery context, fissural fluid and rapid improvement to identify delayed fluid clearance.','newborn'),
q('Pediatrics','Respiratory','Meconium aspiration chemical injury','A post-term newborn delivered through thick meconium has respiratory distress. Imaging shows patchy opacities with areas of hyperinflation. Which combined effect most directly contributes to the lung disease?', 'Airway obstruction with inflammatory surfactant dysfunction', 'Aspirated meconium can obstruct small airways, injure the lung chemically and impair surfactant function. Partial obstruction can cause air trapping, explaining patchy hyperinflation rather than a uniform isolated deficiency of central respiratory drive.', [['Pure anemia without pulmonary injury','Anemia does not account for the aspiration-associated patchy lung abnormalities.'],['Complete bilateral pleural fluid replacement','The described imaging is airway and parenchymal disease rather than large effusions.'],['Isolated nasal septal deviation','An upper nasal abnormality does not explain diffuse meconium-related lung injury.']], 'Explain mixed obstruction and inflammatory injury after meconium aspiration.','newborn'),
q('Pediatrics','Respiratory','Persistent pulmonary hypertension newborn shunt','A term newborn remains severely hypoxemic despite adequate ventilation. Echocardiography shows elevated pulmonary arterial pressure with right-to-left ductal flow and no structural heart defect. Which adaptation has failed?', 'Normal postnatal decline in pulmonary vascular resistance', 'Persistent high pulmonary resistance maintains right-to-left flow through fetal communication pathways and bypasses pulmonary oxygenation. The absence of structural heart disease distinguishes this vascular transition problem from a fixed cyanotic cardiac malformation.', [['Normal closure of a ventricular septal defect','No structural septal defect is present and the problem is vascular resistance.'],['Conversion of fetal hemoglobin to adult hemoglobin alone','Hemoglobin transition does not explain pressure-driven ductal right-to-left flow.'],['Complete cessation of systemic vascular resistance','The demonstrated elevated pulmonary pressure localizes the main transition failure.']], 'Use ductal flow direction and normal cardiac anatomy to identify failed pulmonary transition.','newborn'),
q('Pediatrics','Respiratory','Congenital diaphragmatic hernia hypoplasia','A newborn has severe respiratory distress, a scaphoid abdomen and bowel loops occupying the left chest on imaging. Which underlying pulmonary consequence contributes substantially to respiratory failure?', 'Pulmonary hypoplasia', 'Herniation of abdominal organs during fetal development can impair lung growth as well as displace the mediastinum. The small pulmonary vascular bed may also promote pulmonary hypertension, so respiratory failure is not simply a postnatal mechanical compression phenomenon.', [['Excess development of normal alveoli','The fetal thoracic crowding impairs rather than increases normal lung development.'],['Isolated mucosal edema of the larynx','That does not explain intrathoracic bowel and reduced fetal lung growth.'],['Primary absence of gastric acid secretion','Gastric acid production is not the cause of the pulmonary developmental defect.']], 'Connect prenatal thoracic visceral herniation with reduced lung development.','newborn'),
q('Pediatrics','Gastrointestinal','Esophageal atresia distal fistula','A newborn coughs and becomes cyanotic with the first feed. An orogastric tube coils in the upper esophagus, while abdominal imaging shows gas in the stomach and bowel. What explains the distal intestinal gas?', 'A distal tracheoesophageal fistula', 'An upper blind esophageal pouch explains the coiled tube and feeding difficulty. Gas entering the distal esophagus from the trachea through a fistula explains intestinal aeration despite interruption of normal esophageal continuity.', [['A completely isolated esophageal atresia without any fistula','Without a distal airway connection, the bowel would usually lack this gas pathway.'],['Normal passage through an intact esophagus','The coiled tube establishes interruption of normal esophageal continuity.'],['Pyloric stenosis alone','Pyloric narrowing does not prevent passage of a tube through the esophagus.']], 'Infer a distal airway connection from bowel gas despite esophageal atresia.','pediatric'),
q('Pediatrics','Gastrointestinal','Malrotation midgut volvulus urgency','A 3-day-old develops abrupt bilious vomiting and abdominal pain. Upper gastrointestinal contrast imaging demonstrates a corkscrew duodenum with abnormal position of the duodenojejunal junction. Which complication is most concerning?', 'Midgut volvulus with vascular compromise', 'Malrotation creates a narrow mesenteric base around which the intestine can twist, obstructing lumen and blood supply. Bilious vomiting and a corkscrew configuration warrant urgent surgical attention; a benign feeding intolerance label could delay treatment of ischemic bowel.', [['Normal physiologic reflux requiring no assessment','Bilious emesis and a corkscrew intestinal course are not benign reflux.'],['Isolated lactose intolerance','That does not create mesenteric twisting or vascular compromise.'],['A superficial anal fissure','A distal mucosal tear does not explain proximal twisted bowel anatomy.']], 'Connect malrotation anatomy with a time-sensitive risk of midgut ischemia.','pediatric'),
q('Pediatrics','Gastrointestinal','Meconium ileus cystic fibrosis clue','A newborn has distal bowel obstruction with very thick tenacious meconium. Imaging shows small pellets of meconium in the distal ileum rather than absent rectal ganglion cells. Which underlying disease should be considered?', 'Cystic fibrosis', 'Reduced epithelial chloride and water movement can make intestinal contents unusually thick, producing meconium ileus in cystic fibrosis. The obstructing inspissated material distinguishes this mechanism from the distal aganglionosis of Hirschsprung disease.', [['Isolated congenital hypothyroidism as the only explanation','The characteristic inspissated ileal meconium specifically raises concern for cystic fibrosis.'],['Hirschsprung disease established by absent ganglia','No aganglionosis is described and the obstruction is thick ileal contents.'],['Physiologic normal meconium passage','Mechanical neonatal obstruction is not a normal passage pattern.']], 'Recognize inspissated ileal meconium as a neonatal clue to cystic fibrosis.','pediatric'),
q('Pediatrics','General Principles','Omphalitis invasive infection','A 9-day-old has fever, poor feeding and erythema extending from the umbilical stump onto the abdominal wall. Purulent drainage is present. Which interpretation best fits?', 'Omphalitis with risk of systemic infection', 'Spreading periumbilical inflammation and purulence in a systemically ill newborn indicate infection rather than ordinary cord separation. Neonatal immune vulnerability creates risk of extension and sepsis; a small umbilical source can therefore be clinically serious.', [['Normal uncomplicated cord separation','Spreading redness, pus and systemic symptoms are not normal separation findings.'],['Benign umbilical granuloma alone','A granuloma does not usually explain fever and spreading abdominal cellulitis.'],['Physiologic neonatal jaundice','Bilirubin metabolism does not explain a purulent inflamed umbilical source.']], 'Distinguish infected neonatal umbilical tissue from benign healing changes.','pediatric'),
q('Pediatrics','Hematology','Early neonatal jaundice hemolysis','A newborn becomes jaundiced within 12 hours of birth. Bilirubin is predominantly unconjugated, hemoglobin is low and reticulocytes are elevated. Which explanation is most consistent with the timing and blood findings?', 'Accelerated erythrocyte destruction', 'Jaundice during the first day with anemia and reticulocytosis suggests hemolysis rather than routine physiologic bilirubin accumulation. Identifying the cause requires additional testing, but the blood pattern supports increased bilirubin production from red-cell breakdown.', [['Physiologic jaundice as a sufficient explanation','Very early onset with anemia and reticulocytosis requires a pathologic evaluation.'],['Complete biliary obstruction as demonstrated here','The predominantly unconjugated pattern and hemolysis markers favor increased production.'],['Isolated maternal iron deficiency as the direct bilirubin mechanism','Maternal iron status alone does not explain abrupt neonatal reticulocytic hemolysis.']], 'Use jaundice timing and marrow response to identify neonatal hemolysis.','pediatric'),
q('Pediatrics','General Principles','Low intake neonatal jaundice','A 4-day-old breastfed infant has unconjugated jaundice, few wet diapers and excessive weight loss. The infant latches poorly, stools infrequently and has no anemia. Which contributor best explains the bilirubin rise?', 'Low milk intake with increased enterohepatic bilirubin circulation', 'Inadequate intake reduces stooling and promotes reabsorption of intestinal bilirubin while causing dehydration and weight loss. This early low-intake pattern differs from later breast-milk jaundice in an otherwise thriving infant and needs feeding assessment.', [['Adequate intake proven by breastfeeding alone','The low urine output and excessive weight loss indicate inadequate transfer.'],['Mechanical extrahepatic obstruction established by unconjugated bilirubin','Obstructive cholestasis is more associated with conjugated bilirubin and pale stools.'],['An obligatory need to stop all breastfeeding permanently','Feeding assessment and support address intake without that universal conclusion.']], 'Relate early jaundice to objective evidence of inadequate milk transfer.','pediatric'),
q('Pediatrics','General Principles','Safe sleep supine firm surface','Parents ask how to position their healthy 2-month-old for sleep. The infant has occasional uncomplicated spit-up and no special airway condition. Which routine sleep arrangement best follows safe-sleep guidance?', 'Supine on a firm flat separate sleep surface without soft bedding', 'Routine infant sleep is safest when initiated on the back on a firm flat separate surface with no loose soft objects. Uncomplicated reflux does not justify prone positioning or an inclined sleeper; awake supervised tummy time serves a different purpose.', [['Prone on a pillow to prevent routine spit-up','Prone sleep and soft bedding increase sleep-related risk in routine infant care.'],['Inclined in a car seat for every overnight sleep','Sitting devices are not the routine firm flat sleep surface recommendation.'],['Side-lying with positioning cushions','Side positioning is unstable and added cushions introduce hazards.']], 'Apply safe-sleep guidance despite uncomplicated infant reflux.','sleep','application'),
q('Pediatrics','Renal','Infant urine bag contamination','A febrile non-toilet-trained infant has a urine bag culture growing mixed organisms. No antibiotics have been given and the child is stable. What limitation most directly prevents treating this as definitive culture proof of UTI?', 'High contamination risk of bag-collected specimens', 'Perineal bag specimens can collect skin and stool organisms, especially when growth is mixed. A properly collected catheterized or suprapubic specimen is needed when reliable culture confirmation will guide care; growth alone cannot overcome a flawed collection method.', [['All mixed organisms necessarily indicate invasive kidney infection','Mixed growth from a contamination-prone specimen does not establish pyelonephritis.'],['Urine cultures are never useful in infancy','Reliable cultures can be useful when collection and clinical interpretation are appropriate.'],['A bag specimen is sterile by definition','Contact with perineal skin makes contamination a substantial limitation.']], 'Evaluate specimen quality before interpreting pediatric urinary culture growth.','urine'),
q('Pediatrics','Renal','Vesicoureteral reflux retrograde flow','A child with recurrent febrile urinary infections undergoes voiding imaging showing contrast moving from the bladder into a ureter and renal collecting system. Which structural function is inadequate?', 'The ureterovesical antireflux mechanism', 'Failure of the intramural ureteral valve mechanism permits retrograde urine flow during bladder filling or voiding. This is vesicoureteral reflux, which can contribute to recurrent upper urinary infection; it is distinct from a stone blocking antegrade flow.', [['The glomerular filtration barrier alone','Glomerular protein selectivity does not govern retrograde bladder-to-ureter flow.'],['The pyloric sphincter','A gastric outlet structure does not control urinary reflux.'],['The external anal sphincter','Anal continence does not define the demonstrated ureterovesical flow defect.']], 'Identify the failed antireflux junction from voiding contrast direction.','urine'),
q('Pediatrics','Hematology','Childhood leukemia marrow failure','A 5-year-old has fatigue, bruising, fever and bone pain. Testing shows anemia, thrombocytopenia and circulating blasts. Which process best explains the combination of cytopenias and skeletal symptoms?', 'Leukemic marrow infiltration', 'Expansion of malignant precursor cells can suppress normal hematopoiesis and produce marrow-related bone pain. The combination of multiple cytopenias and blasts distinguishes leukemia from isolated platelet destruction or a simple nutritional anemia.', [['Isolated immune platelet destruction','That does not explain anemia with circulating blasts and marrow-related bone pain.'],['Uncomplicated dietary iron deficiency alone','Iron deficiency does not produce circulating blasts or this broad marrow-failure pattern.'],['Normal childhood growing pains','Growing pains do not account for cytopenias, bruising and blasts.']], 'Integrate blasts, multiple cytopenias and bone pain as marrow infiltration.','pediatric'),
q('Pediatrics','Renal','Wilms tumor renal origin','A 4-year-old has a painless flank mass, microscopic hematuria and hypertension. Imaging demonstrates a large mass arising from the kidney that displaces adjacent structures without extensive calcification. Which diagnosis is most likely?', 'Wilms tumor', 'A renal-origin mass in a young child with hematuria and hypertension is characteristic of Wilms tumor. Imaging localization is more useful than the presence of abdominal enlargement alone; adrenal neuroblastoma often has a different origin and vascular relationship.', [['Adrenal neuroblastoma as proven by any abdominal mass','The documented renal origin and urinary findings favor a renal tumor.'],['Uncomplicated cystitis','A bladder infection does not produce a large solid renal mass.'],['Physiologic palpable kidney in every child','A large mass with hematuria and hypertension is abnormal.']], 'Localize a pediatric abdominal tumor using renal origin and urinary findings.','clinical'),
q('Pediatrics','Nervous System','Neuroblastoma catecholamine clues','A 2-year-old has an irregular abdominal mass crossing the midline, periorbital bruising and bone pain. Urine homovanillic and vanillylmandelic acid levels are elevated. Which diagnosis best fits?', 'Neuroblastoma', 'A sympathetic neural crest tumor can produce catecholamine metabolites and spread to bone or orbital tissues. The irregular mass and metastatic signs with elevated metabolites support neuroblastoma rather than assuming every childhood abdominal mass arises from the kidney.', [['Wilms tumor as the usual catecholamine-producing lesion','Elevated urinary catecholamine metabolites and orbital spread favor neuroblastoma.'],['Simple constipation','Constipation does not account for metastatic signs and catecholamine metabolite elevation.'],['Isolated immune thrombocytopenia','A platelet disorder does not produce a catecholamine-secreting abdominal mass.']], 'Combine abdominal mass characteristics with catecholamine metabolites and metastatic clues.','clinical'),
q('Pediatrics','Musculoskeletal','Rickets growth plate mineralization','A toddler with limited vitamin D intake has delayed walking, bowed legs and widened wrists. Radiographs show metaphyseal cupping and fraying at the growth plates. Which process is impaired?', 'Mineralization of growing bone and cartilage', 'Inadequate mineral availability or metabolism disrupts mineralization at growth plates, producing rickets in children. The metaphyseal changes distinguish this from isolated ligament laxity or adult osteoporosis, where open growth-plate abnormalities are absent.', [['Normal bone growth with isolated skin disease','The characteristic metaphyseal abnormalities indicate skeletal mineralization disease.'],['Only mature cortical bone resorption without growth-plate involvement','Rickets specifically affects mineralization in the growing skeleton.'],['Excess mineral deposition in every growth plate','The process is insufficient effective mineralization rather than excessive deposition.']], 'Interpret growth-plate cupping and fraying as defective childhood mineralization.','pediatric'),
q('Pediatrics','Musculoskeletal','Osteogenesis imperfecta collagen phenotype','A child has repeated fractures after minor trauma, blue sclerae, early hearing difficulty and a family history of similar fragility. Which structural protein is most commonly affected?', 'Type I collagen', 'Type I collagen contributes to bone, scleral and auditory connective-tissue integrity. A multisystem inherited fragility pattern supports osteogenesis imperfecta, while isolated accidental injury does not explain blue sclerae and familial hearing changes.', [['Type IV collagen exclusively','Type IV collagen disease more typically affects basement-membrane structures.'],['Dystrophin','Dystrophin loss causes muscle fiber injury rather than this primary collagen fragility pattern.'],['Fibrinogen as the bone matrix scaffold','Fibrinogen is a coagulation protein rather than the main structural bone collagen.']], 'Connect inherited fracture fragility with extraskeletal collagen findings.','clinical'),
q('Pediatrics','Musculoskeletal','Duchenne dystrophy pseudohypertrophy','A 4-year-old boy has delayed motor milestones, frequent falls and uses his hands to climb up his thighs when standing. Calves appear enlarged and creatine kinase is markedly elevated. What explains the apparent calf enlargement?', 'Replacement of damaged muscle by fat and connective tissue', 'Dystrophin-related myofiber injury causes progressive weakness despite enlarged-looking calves. Fat and fibrous tissue can replace functioning muscle, producing pseudohypertrophy; gross size therefore does not indicate increased contractile strength.', [['A true increase in healthy contractile fibers accounting for superior strength','The child is weak and the enlargement reflects noncontractile replacement.'],['Fluid-filled calf tumors in every case','The characteristic diffuse enlargement does not require discrete tumors.'],['Normal exercise adaptation from increased activity','Progressive weakness and marked enzyme elevation indicate pathologic muscle injury.']], 'Explain calf pseudohypertrophy in a proximal childhood myopathy.','clinical'),
q('Pediatrics','Musculoskeletal','Osteosarcoma osteoid diagnosis','An adolescent has progressive pain and swelling near the distal femur. Imaging shows an aggressive metaphyseal lesion, and biopsy demonstrates malignant cells producing osteoid. Which tumor is diagnosed?', 'Osteosarcoma', 'Malignant osteoid production is the defining tissue feature of osteosarcoma, commonly arising near an adolescent growth plate. Age and location support the interpretation, but tissue matrix production distinguishes it more specifically from other aggressive bone tumors.', [['Ewing sarcoma','Ewing tumor is not defined by malignant cells producing osteoid.'],['Simple bone cyst','A benign fluid cavity does not contain malignant osteoid-producing cells.'],['Osteoarthritis','Degenerative joint disease does not cause this adolescent malignant metaphyseal lesion.']], 'Use malignant osteoid rather than imaging aggression alone to identify osteosarcoma.','clinical'),
q('Pediatrics','Musculoskeletal','Ewing sarcoma diaphyseal small round cells','A 12-year-old has localized bone pain, low-grade fever and a destructive diaphyseal lesion with laminated periosteal reaction. Biopsy shows a small round-cell tumor with an EWSR1-associated rearrangement. Which diagnosis fits?', 'Ewing sarcoma', 'A diaphyseal small round-cell tumor with an EWSR1-associated molecular finding supports Ewing sarcoma. Fever can mimic infection, so symptoms or periosteal reaction alone are insufficient; the biopsy and molecular context distinguish the malignant lesion.', [['Osteosarcoma established without osteoid','The supplied small-cell molecular pattern differs from malignant osteoid production.'],['Osgood-Schlatter traction apophysitis','An apophyseal overuse lesion does not explain a destructive diaphyseal tumor.'],['Normal periosteal growth','Destructive imaging and tumor histology are not physiologic growth findings.']], 'Distinguish a diaphyseal small round-cell bone malignancy from infection mimics.','clinical'),
q('Pediatrics','Gastrointestinal','Functional constipation overflow','A toilet-trained child passes very large hard stools and avoids defecation because it hurts. Underwear is intermittently soiled with small amounts of loose stool, and a rectal stool mass is present. Which mechanism explains the soiling?', 'Overflow around retained impacted stool', 'Painful defecation promotes withholding and progressive rectal stool retention. Softer material can leak around the impaction, creating apparent diarrhea; treating it as primary infectious diarrhea misses the underlying retention cycle.', [['A deliberate behavior proved by soiled underwear','Overflow can occur without intentional control and should not be assumed deliberate.'],['Primary secretory diarrhea without retained stool','The palpable stool mass and withholding history support overflow.'],['Complete absence of colonic contents','The examination directly demonstrates substantial retained stool.']], 'Explain apparent loose-stool incontinence in a child with fecal retention.','pediatric'),
q('Pediatrics','General Principles','Primary nocturnal enuresis counseling','A 7-year-old has never been consistently dry overnight but has normal daytime continence, no dysuria, normal growth and a normal urinalysis. What counseling principle is appropriate during management?', 'Avoid blame or punishment for nighttime wetting', 'Primary monosymptomatic nocturnal enuresis can reflect maturation and sleep-related bladder control rather than deliberate misbehavior. A reassuring assessment supports nonpunitive management; new daytime symptoms, polyuria or urinary infection would require reassessment.', [['Punishment is needed because wetting is always intentional','Nighttime enuresis is not ordinarily deliberate behavior.'],['A normal urinalysis proves all future evaluation is unnecessary','New symptoms or a changing pattern can require renewed assessment.'],['The child necessarily has severe renal failure','Normal growth and the isolated nighttime pattern do not establish kidney failure.']], 'Use a nonpunitive approach after distinguishing isolated nighttime wetting from warning symptoms.','urine','application'),
q('Pediatrics','Behavioral Health','Autism social communication pattern','A 3-year-old has limited joint attention, does not use gestures to share interests and repeatedly lines up toys. Hearing is normal. Which combination is central to the diagnostic assessment?', 'Social communication differences and restricted repetitive behaviors', 'Autism assessment integrates social communication with restricted or repetitive behaviors across development. Normal hearing reduces one alternative explanation but does not establish the diagnosis alone; language delay without the additional pattern is not equivalent.', [['Language delay alone is sufficient in every child','Language delay has many causes and does not by itself establish autism.'],['Normal hearing excludes developmental disorders','Hearing status does not exclude social communication and behavioral differences.'],['An isolated late bedtime is the defining criterion','Sleep timing alone does not define the core developmental pattern.']], 'Identify both core developmental domains rather than diagnosing autism from speech delay alone.','clinical'),
q('Pediatrics','Behavioral Health','ADHD cross setting impairment','A 9-year-old has persistent distractibility and impulsivity documented at both home and school for more than six months, with academic and peer impairment. Vision, hearing and sleep are adequate. Which feature strengthens an ADHD assessment?', 'Symptoms with impairment in more than one setting', 'ADHD assessment requires a persistent developmentally inappropriate pattern with functional impact across settings. Cross-setting corroboration helps distinguish a broad disorder from a difficulty limited to one classroom context; rating scales complement rather than replace clinical assessment.', [['A single teacher complaint is always diagnostic','One setting alone does not establish the required broader impairment pattern.'],['Normal intelligence rules out ADHD','Attention regulation difficulties can occur across intellectual ability levels.'],['Any active child requires medication','Activity level alone does not establish diagnosis or dictate treatment.']], 'Use corroborated functional impairment across settings in attention assessment.','clinical'),
q('Pediatrics','General Principles','Nonaccidental injury developmental compatibility','A 3-month-old who cannot roll has several unexplained bruises over the torso and fractures of different ages. The stated history is a short fall onto a padded mat. Which consideration is most important?', 'Possible inflicted injury requires a safeguarding assessment', 'Injuries inconsistent with developmental ability and the reported mechanism raise concern for inflicted trauma. The pattern warrants careful evaluation and safeguarding procedures while considering medical mimics; the history alone neither excludes abuse nor proves a particular perpetrator.', [['Any caregiver explanation excludes inflicted injury','The explanation must be assessed against development, examination and injury mechanics.'],['A particular person is proven guilty by these findings alone','Clinical concern warrants assessment but does not independently identify a perpetrator.'],['Bruising is expected in every nonmobile infant','Unexplained bruising in a nonmobile infant is a significant warning sign.']], 'Compare injury pattern with developmental ability and mechanism without overclaiming perpetrator certainty.','clinical'),
q('Pediatrics','General Principles','Iron deficiency excessive milk','A 2-year-old drinks large volumes of cow milk and eats few iron-rich foods. He has pallor, microcytosis, low ferritin and high iron-binding capacity without inflammation. Which dietary factor most contributes?', 'Displacement of iron-rich foods by excessive milk intake', 'Cow milk is relatively low in iron and large volumes can displace iron-containing complementary foods. Low ferritin with increased binding capacity supports depleted iron stores; the dietary pattern is a modifiable contributor rather than proof of an inherited hemoglobin disorder.', [['Cow milk is an exceptionally iron-rich complete toddler diet','Excess milk can displace more appropriate iron sources.'],['High ferritin proves iron deficiency here','The supplied ferritin is low, supporting depleted stores.'],['All microcytosis necessarily indicates thalassemia','Dietary context and iron studies support an acquired deficiency pattern.']], 'Connect a toddler dietary pattern to biochemical evidence of iron depletion.','pediatric'),
q('Pediatrics','General Principles','Failure to thrive feeding observation','A 5-month-old has poor weight gain without diarrhea, recurrent infection or abnormal examination findings. During observed feeding, caregivers mix formula with twice the recommended water to make it last longer. Which factor most directly explains the growth problem?', 'Insufficient energy delivery from overly diluted formula', 'Excess water dilution reduces calories and nutrients per feed and can also create electrolyte risk. Observing preparation identifies a concrete intake problem that reported feeding volume alone misses; normal examination does not establish adequate nutritional delivery.', [['The stated bottle volume guarantees adequate calories','Caloric concentration matters as well as the volume offered.'],['An inherited metabolic disorder is proven by low weight alone','A directly observed intake problem provides an immediate alternative explanation.'],['Extra dilution always improves infant hydration safely','Overdilution can impair nutrition and disturb sodium balance.']], 'Evaluate feed concentration rather than assuming bottle volume represents adequate intake.','pediatric'),
q('Pediatrics','Nervous System','Absence seizure versus inattention','An 8-year-old has many daily abrupt five-second staring spells with eyelid flutter and immediate resumption of activity. Hyperventilation reproduces an event with generalized 3-Hz spike-wave EEG activity. Which diagnosis fits?', 'Childhood absence epilepsy', 'Brief stereotyped lapses with abrupt recovery and generalized three-Hz spike-wave activity are typical of absence seizures. Frequent spells can resemble inattention, but the electroclinical pattern distinguishes them from ordinary daydreaming or a prolonged postictal focal event.', [['Ordinary daydreaming confirmed by school complaints','Daydreaming does not produce the characteristic generalized EEG discharge.'],['Focal impaired-awareness seizure with prolonged postictal confusion','The very brief frequent events and immediate recovery favor absence seizures.'],['Simple febrile seizures','These repeated afebrile staring spells are not fever-provoked generalized convulsions.']], 'Use stereotyped timing and provoked EEG findings to distinguish seizures from inattention.','clinical'),
q('Obstetrics','Pregnancy','Bacterial vaginosis dysbiosis','A patient has thin homogeneous gray discharge with a fishy odor. Vaginal pH is 5.4 and microscopy shows epithelial cells coated with bacteria with few inflammatory cells. Which process best explains the findings?', 'Vaginal microbial dysbiosis with reduced lactobacillus predominance', 'Clue cells, elevated pH and amine odor support bacterial vaginosis, a shift in the vaginal microbial community. The scant inflammation and absence of fungal structures distinguish the pattern from symptomatic candidiasis; symptoms alone do not establish a specific cause.', [['Invasive candidal hyphae as shown by clue cells','Clue cells are bacteria-coated epithelial cells rather than fungal hyphae.'],['Normal lactobacillus-dominant acidic flora','The elevated pH and characteristic microscopy indicate altered flora.'],['A diagnosis of gonorrhea established by odor alone','Odor and clue cells do not identify a cervical gonococcal infection.']], 'Integrate pH, odor and clue cells to identify vaginal dysbiosis.','bv'),
q('Obstetrics','Pregnancy','Candidiasis microscopy and pH','A patient develops intense vulvar itching and thick discharge after an antibiotic course. Vaginal pH is 4.2 and microscopy shows budding yeast with pseudohyphae. Which diagnosis best fits?', 'Vulvovaginal candidiasis', 'Vulvar pruritus with yeast forms supports symptomatic candidiasis, which commonly occurs without elevated vaginal pH. Antibiotic exposure can alter the local microbial environment, but microscopy and symptoms distinguish infection from an incidental asymptomatic yeast culture.', [['Bacterial vaginosis','That typically has elevated pH, clue cells and less intense vulvar inflammation.'],['Trichomoniasis established by pseudohyphae','Trichomonads are protozoa rather than budding fungal forms.'],['Normal flora requiring no interpretation of symptoms','The combination of symptoms and fungal microscopy supports symptomatic disease.']], 'Combine normal vaginal acidity with inflammatory symptoms and fungal microscopy.','candida'),
q('Obstetrics','Pregnancy','Trichomoniasis motile organisms','A patient has vaginal irritation and frothy discharge with elevated vaginal pH. Wet mount demonstrates motile flagellated organisms. Which pathogen most directly accounts for the findings?', 'Trichomonas vaginalis', 'Motile flagellated protozoa on wet preparation identify trichomonads in the appropriate symptomatic setting. Elevated pH is compatible but nonspecific; a negative wet mount would not reliably exclude infection because microscopy has limited sensitivity.', [['Candida albicans','Candida appears as yeast or hyphal forms, not motile flagellated protozoa.'],['Gardnerella as a flagellated protozoan','Gardnerella is a bacterium and does not have this protozoal microscopy.'],['Human papillomavirus','A viral infection is not visualized as motile flagellates on wet mount.']], 'Identify a protozoal vaginitis from motility while recognizing wet-mount sensitivity limits.','trichomonas'),
q('Obstetrics','Pregnancy','Cervicitis mucopurulent localization','A sexually active patient has postcoital spotting and mucopurulent discharge emerging from the cervical os. The cervix bleeds with gentle swabbing, while vaginal microscopy shows no yeast or trichomonads. Which localization is best?', 'Cervical inflammation', 'Mucopurulent endocervical discharge and contact bleeding support cervicitis rather than automatically assigning a vaginal infection. Testing for relevant sexually transmitted pathogens and assessment for upper tract involvement follow from the cervical localization.', [['Vaginal candidiasis established despite absent fungal findings','The discharge originates at the cervix and the inflammation is cervical.'],['A normal cervix because the discharge is not painful','Cervicitis may be minimally painful despite visible mucopus and friability.'],['Ovarian torsion','Torsion causes an acute adnexal pain syndrome rather than isolated cervical mucopus.']], 'Localize genital discharge using its origin and contact bleeding.','clinical'),
q('Obstetrics','Pregnancy','Tubo ovarian abscess imaging','A patient with fever, pelvic pain and cervical motion tenderness has a complex thick-walled adnexal collection with surrounding inflammation. Pregnancy testing is negative. Which complication best explains the mass?', 'Tubo-ovarian abscess', 'Pelvic inflammatory disease can form a purulent inflammatory complex involving the tube and ovary. Fever and a thick-walled collection distinguish this from a simple physiologic ovarian cyst; pregnancy exclusion reduces one important alternative but does not identify the mass alone.', [['Simple ovulatory follicle','A normal follicle does not explain systemic fever and a thick inflammatory collection.'],['Uncomplicated uterine leiomyoma','The lesion is adnexal and inflammatory rather than a uterine smooth-muscle mass.'],['Normal early gestational sac','Pregnancy testing is negative and the imaging describes an inflammatory collection.']], 'Integrate infection signs and complex adnexal imaging to recognize a suppurative complication.','clinical'),
q('Obstetrics','Pregnancy','Bartholin gland abscess anatomy','A patient has severe unilateral vulvar pain and a fluctuant mass at the posterolateral vaginal opening. The tender swelling lies near the typical 5 o clock gland location. Which structure is involved?', 'Bartholin duct or gland', 'Bartholin glands drain near the posterior vaginal introitus, and an obstructed infected duct can form a painful fluctuant abscess. The location distinguishes this from an anterior periurethral lesion or an intrapelvic ovarian process.', [['Skene gland at the anterior urethral opening','Skene glands are periurethral rather than posterolateral at the introitus.'],['Ovary within the vulvar skin','An ovary is intrapelvic and does not occupy this superficial gland location.'],['Uterine cervix protruding as a fluctuant abscess','The cervix does not normally lie in this posterolateral superficial position.']], 'Localize a painful posterolateral introital mass to the Bartholin apparatus.','clinical','application'),
q('Obstetrics','Dermatology','Lichen sclerosus vulvar scarring','A postmenopausal patient has chronic vulvar itching, thin porcelain-white plaques and progressive loss of normal vulvar architecture. The vaginal mucosa is spared. Which diagnosis best fits?', 'Vulvar lichen sclerosus', 'A chronic pruritic white sclerotic vulvar process with architectural change and vaginal sparing suggests lichen sclerosus. Persistent focal ulceration or changing lesions require assessment because symptoms alone cannot exclude associated neoplasia.', [['Uncomplicated candidiasis as the cause of chronic scarring','Yeast infection does not typically produce this sclerotic architectural loss pattern.'],['Normal aging with no need to evaluate symptoms','Persistent pruritus and structural change require clinical assessment.'],['Trichomoniasis defined by white plaques','Trichomoniasis does not characteristically produce porcelain-white sclerotic plaques.']], 'Recognize a chronic sclerosing vulvar disorder using distribution and architectural change.','clinical'),
q('Obstetrics','Pregnancy','Cervical lesion bleeding assessment','A 48-year-old has repeated postcoital bleeding and a visibly irregular friable cervical lesion. A previous screening test was normal several years ago. Which principle most appropriately guides evaluation?', 'A symptomatic visible lesion requires diagnostic assessment', 'Screening results describe an earlier screening context and do not exclude a current visible lesion. Recurrent contact bleeding with an abnormal cervix requires diagnostic evaluation, often including tissue assessment, rather than reassurance based solely on a past result.', [['An old negative screening test excludes every current cervical lesion','Screening does not replace evaluation of new symptoms and visible abnormalities.'],['Repeat screening alone always substitutes for evaluating a mass','A gross lesion is a diagnostic problem rather than routine asymptomatic screening.'],['The lesion is definitely benign because bleeding is painless','Painless contact bleeding does not establish benign histology.']], 'Distinguish diagnostic evaluation of a symptomatic cervical lesion from routine screening.','clinical','application'),
q('Obstetrics','Pregnancy','Granulosa tumor estrogenic effect','A postmenopausal patient develops uterine bleeding and an ovarian mass. Endometrial tissue is hyperplastic; the ovarian tumor contains Call-Exner bodies and nuclear grooves. Which tumor effect explains the bleeding?', 'Estrogen production by a granulosa cell tumor', 'Granulosa cell tumors may secrete estrogen, stimulating the postmenopausal endometrium and causing hyperplasia or bleeding. The ovarian histology and endometrial response connect the mass to endocrine activity rather than treating the bleeding as an unrelated normal menstrual cycle.', [['Isolated androgen resistance in uterine cells','That does not explain estrogen-responsive endometrial hyperplasia and tumor histology.'],['Complete absence of all ovarian hormone activity','The endometrial proliferation suggests an active estrogenic source.'],['Normal resumption of ovulation after menopause','The ovarian neoplasm and endometrial changes provide a pathologic explanation.']], 'Connect a sex-cord stromal ovarian tumor to estrogen-driven endometrial effects.','clinical'),
q('Obstetrics','Pregnancy','Mature teratoma tissue origin','A young adult has an ovarian mass containing fat, calcification and a toothlike structure. Histology shows mature skin, cartilage and respiratory epithelium without immature components. Which diagnosis fits?', 'Mature cystic teratoma', 'A mature teratoma contains differentiated tissues from germ-cell lineage, often including fat and toothlike structures. The supplied mature histology supports this diagnosis; tissue diversity alone does not establish malignant behavior.', [['Serous cystadenoma','A serous epithelial cyst does not typically contain teeth and multiple mature tissue types.'],['Immature teratoma established despite no immature elements','Immature components must be demonstrated rather than inferred from any mixed tissue.'],['Uterine leiomyoma','A uterine smooth-muscle tumor does not explain a fat-containing ovarian lesion.']], 'Use differentiated tissue diversity to classify a germ-cell ovarian mass.','clinical'),
q('Obstetrics','Pregnancy','Epithelial ovarian malignancy presentation','A 67-year-old has persistent bloating, early satiety and increasing abdominal girth. Imaging shows a complex adnexal mass, ascites and omental nodularity. Which process is most concerning?', 'Ovarian malignancy with peritoneal spread', 'A complex adnexal lesion with ascites and omental disease in a postmenopausal patient is concerning for ovarian malignancy and transcoelomic spread. Nonspecific digestive symptoms do not make the pelvic and peritoneal findings benign; histology is needed for classification.', [['Uncomplicated functional ovulatory cyst','A postmenopausal complex mass with omental lesions is not a routine functional cyst pattern.'],['Isolated irritable bowel syndrome','A functional bowel disorder does not explain the adnexal mass and peritoneal nodules.'],['Normal menopause-related fluid accumulation','Ascites with nodularity is abnormal and requires evaluation.']], 'Integrate subtle persistent symptoms with pelvic and peritoneal evidence of malignancy.','clinical'),
q('Obstetrics','Pregnancy','Intrahepatic cholestasis pruritus','At 32 weeks a patient develops intense itching of the palms and soles, worse at night, without a primary rash. Serum bile acids are elevated. Which diagnosis best fits?', 'Intrahepatic cholestasis of pregnancy', 'Pruritus without a primary skin eruption plus elevated bile acids supports pregnancy-associated cholestasis. Excoriations may develop secondarily, but they do not create a primary inflammatory rash; the diagnosis has fetal implications beyond maternal discomfort.', [['Polymorphic eruption of pregnancy as shown by normal skin','That disorder usually has a primary urticarial eruption, not isolated bile-acid elevation.'],['Normal skin stretching alone','Localized stretching does not explain elevated serum bile acids.'],['Contact dermatitis of both palms proved by itching','A contact exposure and primary dermatitis are not demonstrated.']], 'Use absence of a primary rash and elevated bile acids to identify cholestatic pruritus.','skin'),
q('Obstetrics','Pregnancy','Acute fatty liver pregnancy hypoglycemia','At 36 weeks a patient develops nausea, jaundice, confusion, hypoglycemia and prolonged coagulation times. There is no marked thrombocytopenia, and liver failure evolves rapidly. Which pregnancy-associated disease is most concerning?', 'Acute fatty liver of pregnancy', 'Late-pregnancy liver dysfunction with hypoglycemia and impaired synthetic function raises concern for acute fatty liver. It can overlap with hypertensive syndromes, so the pattern is not diagnosed from one test; profound metabolic and coagulation abnormalities distinguish it from isolated pruritic cholestasis.', [['Uncomplicated cholestasis with no hepatic failure','Hypoglycemia and coagulopathy indicate more than isolated itching with bile-acid elevation.'],['Physiologic pregnancy nausea','Late progressive liver failure is not normal pregnancy nausea.'],['Isolated gestational thrombocytopenia','A platelet-only condition does not explain hypoglycemia and hepatic synthetic failure.']], 'Distinguish late-pregnancy liver failure using hypoglycemia and synthetic dysfunction.','clinical'),
q('Obstetrics','Pregnancy','Sheehan syndrome postpartum pituitary','A patient survives severe postpartum hemorrhage. Weeks later she cannot lactate, remains amenorrheic and has fatigue with low pituitary-dependent hormone levels. Which injury best explains the combination?', 'Ischemic injury to the anterior pituitary', 'Severe hemorrhagic hypotension can injure the enlarged pregnancy-associated pituitary, causing loss of prolactin and other anterior hormones. Failure to lactate with multiple endocrine deficits supports Sheehan syndrome rather than isolated mechanical breastfeeding difficulty.', [['Isolated mammary duct obstruction','A local breast problem does not explain multiple pituitary hormone deficits.'],['Primary ovarian failure as the only lesion','Ovarian failure alone does not explain absent prolactin-dependent lactation.'],['Excess growth hormone secretion','Hormone excess does not fit the broad low-hormone postischemic pattern.']], 'Link postpartum shock with combined anterior pituitary hormone loss.','clinical'),
q('Obstetrics','Endocrine','Postpartum thyroiditis destructive release','Three months after delivery, a patient has palpitations with low TSH and elevated free thyroxine. There is no eye disease, thyroid-stimulating antibodies are negative and the thyrotoxic phase is followed by hypothyroidism. Which mechanism fits?', 'Destructive release of stored thyroid hormone', 'Postpartum autoimmune thyroid inflammation can release preformed hormone, followed by temporary or persistent hypothyroidism as stores and gland function decline. The biphasic course and absent stimulating antibodies favor thyroiditis over sustained receptor-driven hormone synthesis.', [['Persistent receptor stimulation as demonstrated by positive antibodies','The supplied antibody result and biphasic course favor destructive thyroiditis instead.'],['An isolated ovarian estrogen surge','That does not explain the measured thyroid hormone sequence.'],['Permanent absence of thyroid tissue since birth','The acquired postpartum biphasic course indicates an inflammatory process.']], 'Distinguish destructive postpartum thyroiditis from sustained stimulatory hyperthyroidism.','thyroid'),
q('Obstetrics','Pregnancy','Lactational breast abscess collection','A breastfeeding patient has fever and a tender erythematous breast. Despite initial care, a focal fluctuant area develops, and ultrasound shows a drainable fluid collection. Which complication has occurred?', 'Breast abscess', 'A localized fluid collection in an inflamed lactating breast supports abscess formation. The transition from diffuse inflammation to a discrete collection matters because source control may be needed; a palpable mass should not automatically be dismissed as simple milk fullness.', [['Simple engorgement without a collection','Engorgement alone does not explain a focal infected fluid cavity.'],['Fibroadenoma as the cause of fever and fluctuance','A benign solid tumor does not best explain an evolving inflammatory collection.'],['Normal lactation with no pathologic process','Fever and a focal abscess are not physiologic milk production.']], 'Identify a focal suppurative complication of lactational breast inflammation.','clinical'),
q('Obstetrics','Pregnancy','Preterm labor cervical change','At 30 weeks a patient has regular painful contractions. Repeat cervical examination over two hours shows progressive dilation and effacement. Membranes are intact and there is no infection. Which finding distinguishes labor from contractions alone?', 'Progressive cervical change', 'Regular contractions accompanied by cervical dilation or effacement support preterm labor. Contractions alone can occur without established labor; documented cervical progression supplies the additional evidence needed rather than using discomfort intensity as the sole criterion.', [['Pain intensity alone regardless of cervical findings','Painful contractions do not by themselves establish progressive labor.'],['Any single contraction before term','Intermittent uterine activity may occur without labor.'],['A normal fetal heart rate excludes labor','Fetal status does not determine whether the cervix is changing.']], 'Use objective cervical progression to distinguish preterm labor from isolated contractions.','labor','application'),
q('Obstetrics','Pregnancy','Cervical insufficiency painless dilation','A patient at 20 weeks has pelvic pressure without contractions. Examination shows painless cervical dilation with membranes bulging through the os. She previously had a painless second-trimester loss. Which process is most likely?', 'Cervical insufficiency', 'Recurrent painless midtrimester dilation suggests inability of the cervix to maintain pregnancy rather than typical contraction-driven preterm labor. Infection and membrane status still require assessment, but the recurrent timing and lack of contractions are key discriminators.', [['Term physiologic cervical ripening','The second-trimester timing and recurrent losses are not normal term ripening.'],['Typical painful active labor established by dilation alone','The painless presentation with prior similar loss favors a cervical structural problem.'],['Ectopic pregnancy in the fallopian tube','The pregnancy is intrauterine with membranes extending through the cervix.']], 'Distinguish recurrent painless midtrimester cervical dilation from contraction-driven labor.','clinical'),
q('Obstetrics','Pregnancy','Prelabor membrane rupture confirmation','At 31 weeks a patient reports a sudden gush of clear fluid without contractions. Sterile speculum examination shows fluid pooling and leakage from the cervical os, with ferning on microscopy. What diagnosis is supported?', 'Preterm prelabor rupture of membranes', 'Fluid visibly leaking from the os with pooling and ferning supports membrane rupture before labor at a preterm gestation. History alone can be confused with urine or discharge, while cervical dilation is not required to establish rupture.', [['Urinary incontinence is proven by any clear fluid','The demonstrated cervical leakage and ferning support amniotic fluid rather than urine.'],['Preterm labor established despite absent contractions','Ruptured membranes and labor are distinct diagnoses and may not occur simultaneously.'],['Normal vaginal discharge with intact membranes confirmed','Visible os leakage with the supporting findings argues against intact membranes.']], 'Confirm membrane rupture using source of leakage and supportive fluid examination.','labor'),
q('Obstetrics','Pregnancy','Intraamniotic infection intrapartum clues','During labor after prolonged membrane rupture, a patient develops fever, uterine tenderness and fetal tachycardia. Amniotic fluid is malodorous. Which diagnosis best integrates the findings?', 'Intraamniotic infection', 'Maternal fever with uterine tenderness, fetal tachycardia and malodorous fluid raises concern for infection involving the amniotic compartment. Prolonged rupture increases risk; fetal tachycardia alone is nonspecific, but the combined findings support an infectious obstetric process.', [['Normal labor physiology alone','The fever, tenderness and malodorous fluid exceed ordinary labor changes.'],['Isolated cystitis as definitively established','The described findings localize concern to the intrauterine compartment.'],['Placenta previa as the explanation for fever','Previa primarily concerns placental location and bleeding rather than this infectious pattern.']], 'Integrate maternal and fetal inflammatory findings after membrane rupture.','clinical'),
q('Obstetrics','Pregnancy','Twin twin transfusion unequal fluid','A monochorionic diamniotic twin pregnancy shows one fetus with oligohydramnios and a small bladder, while the cotwin has polyhydramnios and cardiomegaly. Which mechanism best explains the discordance?', 'Unbalanced intertwin flow through placental vascular connections', 'Shared placental vessels can transfer blood unequally, producing a relatively hypovolemic donor with low urine output and a volume-loaded recipient with excess urine and cardiac strain. The fluid pattern reflects fetal hemodynamics rather than different amniotic membrane permeability alone.', [['Independent placentas with no possible vascular communication','The monochorionic setting permits shared placental vascular connections.'],['Both fetuses necessarily have identical circulating volume','Donor and recipient hemodynamics are unequal in this syndrome.'],['Maternal water intake selectively entering one sac','That does not explain the paired bladder and cardiac differences.']], 'Connect shared placental vascular flow with donor and recipient fluid findings.','clinical'),
q('Obstetrics','Pregnancy','Oligohydramnios renal agenesis','At 22 weeks, ultrasound shows severe oligohydramnios, absent fetal kidneys and no visible bladder filling. Which missing fetal contribution most directly explains the low fluid volume?', 'Fetal urine production', 'Fetal urine becomes a major contributor to amniotic fluid in the second half of pregnancy. Bilateral renal absence prevents this input, explaining severe oligohydramnios and risking impaired lung development; maternal hydration cannot replace the absent fetal renal function.', [['Fetal salivary secretion as the principal fluid source','Saliva is not the major second-half amniotic fluid contribution.'],['Maternal red-cell production','Maternal erythropoiesis does not directly fill the amniotic cavity.'],['Placental blood draining freely into the amniotic sac','Normal amniotic fluid is not produced by placental hemorrhage.']], 'Connect absent fetal renal function to low amniotic fluid.','clinical'),
q('Obstetrics','Pregnancy','Polyhydramnios impaired fetal swallowing','A fetus has marked polyhydramnios with a persistently small stomach bubble and suspected esophageal obstruction. Which fluid-handling pathway is impaired?', 'Fetal swallowing and gastrointestinal absorption of amniotic fluid', 'Swallowing normally removes fluid from the amniotic cavity and permits gastrointestinal absorption. Obstruction can reduce that pathway and contribute to polyhydramnios; excess fluid is not invariably due to increased fetal urine production.', [['Maternal urine drainage into the amniotic sac','Maternal urinary flow is not the normal amniotic fluid removal pathway.'],['Complete absence of all fetal urine in this case','Absent urine would tend to reduce rather than increase amniotic fluid.'],['Normal swallowing proven by a persistently tiny stomach','A persistently small stomach with suspected obstruction does not demonstrate normal swallowing.']], 'Use gastrointestinal obstruction to explain reduced amniotic fluid removal.','clinical'),
q('Obstetrics','Pregnancy','Placental insufficiency umbilical Doppler','A fetus has growth restriction and an umbilical artery Doppler waveform with markedly increased resistance and absent end-diastolic flow. Which site most directly accounts for this abnormal resistance?', 'Placental vascular bed', 'The umbilical arteries carry fetal blood toward the placenta, so increased downstream resistance reflects placental vascular dysfunction. Absent end-diastolic flow indicates an abnormal flow pattern; it is not simply a measurement of maternal systemic blood pressure.', [['Fetal pulmonary alveoli alone','Umbilical arterial resistance is assessed toward the placental circulation, not ventilated lungs.'],['Maternal ureter','A urinary drainage structure does not determine this fetal arterial waveform.'],['Normal low-resistance placenta in every case','Absent end-diastolic flow is not the usual normal placental Doppler pattern.']], 'Localize increased umbilical arterial resistance to the downstream placental circulation.','clinical'),
q('Obstetrics','Pregnancy','Maternal alloantibody fetal anemia','A pregnant patient has clinically significant red-cell IgG antibodies directed against an antigen expressed by the fetus. The fetus develops anemia. Which mechanism permits the maternal antibody to act?', 'Placental transfer of IgG with fetal erythrocyte targeting', 'Maternal IgG can cross the placenta and bind fetal red-cell antigens, causing hemolysis or other antigen-specific erythroid injury. The mechanism depends on antibody class and fetal antigen expression rather than maternal and fetal ABO labels alone.', [['Maternal IgM freely crossing the placenta as the main mechanism','IgM does not cross the placenta efficiently like IgG.'],['Direct transfer of maternal erythrocytes replacing all fetal cells','Passive IgG transfer, not complete cellular replacement, explains the antibody effect.'],['An antibody effect independent of fetal antigen expression','The fetal target antigen is necessary for antigen-specific injury.']], 'Connect antibody class and fetal antigen expression to immune fetal anemia.','clinical'),
q('Obstetrics','Pregnancy','Fetal anemia middle cerebral velocity','In a pregnancy at risk for fetal red-cell alloimmune disease, Doppler shows increased middle cerebral artery peak systolic velocity. What physiologic change makes this a useful noninvasive anemia marker?', 'Reduced blood viscosity with increased cerebral flow velocity', 'Anemia lowers viscosity and can increase cardiac output and cerebral flow velocity. Middle cerebral artery Doppler uses this hemodynamic response as an anemia assessment tool; it does not directly count fetal erythrocytes or prove the cause of anemia.', [['A direct microscopic red-cell count performed by Doppler','Doppler measures blood flow velocity rather than counting erythrocytes.'],['Increased viscosity caused by anemia','Reduced red-cell concentration generally lowers rather than raises viscosity.'],['Complete cessation of all cerebral blood flow','The finding is increased measurable velocity, not absent flow.']], 'Explain why fetal anemia can elevate cerebral arterial Doppler velocity.','clinical'),
q('Obstetrics','Pregnancy','Amniotic fluid embolism systemic pattern','During delivery a patient abruptly develops severe hypoxemia and cardiovascular collapse followed by diffuse coagulopathic bleeding. No major preceding external hemorrhage explains the initial collapse. Which syndrome is most consistent?', 'Amniotic fluid embolism syndrome', 'Sudden peripartum respiratory and cardiovascular failure with subsequent disseminated coagulopathy is characteristic of amniotic fluid embolism syndrome. It is a clinical diagnosis requiring assessment of competing causes, not proof from an isolated fetal cell finding.', [['Isolated superficial vaginal laceration','A local tear does not explain the initial profound hypoxemia and cardiovascular collapse.'],['Normal postpartum fatigue','Cardiorespiratory collapse with coagulopathy is not physiologic recovery.'],['Uncomplicated urinary infection','The abrupt peripartum multisystem collapse is not a typical uncomplicated urinary infection.']], 'Integrate abrupt peripartum respiratory, circulatory and coagulation failure.','clinical'),
q('Obstetrics','Pregnancy','Umbilical cord prolapse compression','Immediately after membrane rupture, a laboring patient develops prolonged fetal bradycardia. Examination detects a pulsating cord below the presenting fetal head. Which mechanism is most directly threatening fetal oxygen delivery?', 'Compression of umbilical cord vessels', 'A prolapsed cord can be compressed between the presenting part and pelvis after membrane rupture. This compromises placental blood flow and explains abrupt fetal bradycardia; the palpable pulsating structure differentiates the event from an isolated maternal rhythm change.', [['Sudden maternal iron deficiency developing within seconds','That would not explain the immediate prolapsed structure and fetal rate change.'],['Normal fetal sleep causing a palpable cord','Normal sleep does not explain an umbilical cord below the presenting part.'],['Routine cervical mucus obstructing maternal airflow','The primary compromised circulation is fetal-placental, not the maternal airway.']], 'Connect a prolapsed pulsating cord with acute fetal perfusion impairment.','clinical'),
q('Obstetrics','Pregnancy','Occiput posterior persistent labor pain','A patient in labor has persistent back pain and slower descent. Examination identifies the fetal occiput directed toward the maternal sacrum rather than the pubic symphysis. Which fetal position is described?', 'Occiput posterior', 'The occipital landmark defines cephalic fetal position relative to the maternal pelvis. An occiput oriented toward the sacrum is posterior and can be associated with difficult rotation and back discomfort; pain alone would not establish the position.', [['Occiput anterior','Anterior means the occiput faces toward the maternal pubic side.'],['Breech presentation','The described presenting landmark is the occiput of a cephalic fetus.'],['Transverse shoulder presentation','A shoulder presentation does not use a presenting occiput as described.']], 'Apply the occipital landmark to classify a cephalic fetal position.','clinical','application'),
q('Obstetrics','Pregnancy','Ovarian dysgerminoma histology','A 19-year-old has a solid ovarian mass and elevated LDH. Biopsy shows sheets of uniform large clear cells separated by fibrous septa containing lymphocytes. Which ovarian tumor is most consistent?', 'Dysgerminoma', 'A young patient with an ovarian germ-cell tumor showing uniform clear cells and lymphocyte-rich fibrous septa has a pattern characteristic of dysgerminoma. LDH can support assessment but is not independently diagnostic; tissue architecture distinguishes the tumor from a mature teratoma.', [['Mature cystic teratoma','That tumor contains differentiated tissues such as skin or cartilage rather than this uniform clear-cell pattern.'],['Granulosa cell tumor','Granulosa tumors have a sex-cord stromal pattern, often with grooves or Call-Exner bodies.'],['Simple follicular cyst','A benign fluid-filled follicle does not contain this solid malignant germ-cell architecture.']], 'Combine age, supportive tumor marker and histology to classify an ovarian germ-cell tumor.','clinical'),
q('Surgery','Gastrointestinal','Anal fissure painful defecation','A patient has sharp tearing anal pain during defecation followed by a small streak of bright blood. Examination shows a posterior midline linear anodermal tear. Which diagnosis best fits?', 'Anal fissure', 'A visible linear tear with severe defecation-associated pain supports an anal fissure. This differs from the often painless bleeding of internal hemorrhoids; the exact location and lesion matter because bleeding color alone does not identify an anorectal cause.', [['Uncomplicated internal hemorrhoids','These commonly bleed without the sharp pain and visible linear tear.'],['Colonic volvulus','A proximal obstructive process does not explain the focal anodermal lesion.'],['Painless rectal polyp as the demonstrated lesion','The examination identifies a painful linear tear rather than a polyp.']], 'Differentiate painful fissure bleeding from painless internal hemorrhoidal bleeding.'),
q('Surgery','Gastrointestinal','Internal hemorrhoid painless bleeding','A patient has painless bright red bleeding with bowel movements. Anoscopy shows enlarged vascular cushions above the dentate line without a fissure or other lesion. Why is uncomplicated bleeding often painless?', 'The lesion is proximal to somatically sensitive anoderm', 'Internal hemorrhoidal cushions lie above the dentate line, where sensation differs from the somatically innervated distal anoderm. This explains the typical painless presentation, although thrombosis or prolapse complications can change symptoms and bleeding still warrants appropriate assessment.', [['All tissue above the dentate line lacks any innervation','The distinction concerns sensory pathways, not complete absence of innervation.'],['The rectum cannot produce visible bleeding','The observed vascular cushions can bleed into the distal bowel.'],['Every hemorrhoid is necessarily painless even when strangulated','Complications and external lesions can produce substantial pain.']], 'Relate internal hemorrhoid location to its usual sensory presentation.'),
q('Surgery','Gastrointestinal','Perianal abscess focal sepsis','A patient develops constant throbbing anal pain and fever. Examination shows a tender fluctuant swelling beside the anus rather than a linear tear. Which process best explains the findings?', 'Perianal abscess', 'A focal fluctuant perianal collection with fever suggests suppurative infection, commonly arising from an anal gland. Constant pain and systemic symptoms differ from an uncomplicated fissure, while a collection requires consideration of drainage rather than treating only surface irritation.', [['Uncomplicated anal fissure','A fissure is a linear tear and does not itself explain the fluctuant infected collection.'],['Painless internal hemorrhoids','The fever and fluctuance point to infection rather than uncomplicated vascular cushions.'],['Normal perianal skin variation','Systemic symptoms and focal purulence are abnormal findings.']], 'Use fluctuation and systemic symptoms to identify a perianal suppurative collection.'),
q('Surgery','Gastrointestinal','Anal fistula chronic drainage','Months after drainage of a perianal abscess, a patient has recurrent purulent drainage from a small skin opening near the anus. Imaging demonstrates a tract communicating with the anal canal. Which diagnosis fits?', 'Fistula-in-ano', 'A persistent epithelialized or granulating communication from anal canal to perianal skin explains recurrent drainage after an abscess. A fistula is a tract rather than simply another isolated skin pustule, and its relationship to sphincter muscles affects treatment planning.', [['Isolated superficial folliculitis','A demonstrated tract to the anal canal is deeper than a superficial infected follicle.'],['Rectal prolapse','Prolapse involves protruding rectal tissue rather than a draining cutaneous tract.'],['Uncomplicated internal hemorrhoids','Vascular cushions do not explain a purulent skin-to-anal-canal communication.']], 'Recognize a chronic anal communication as a sequela of perianal abscess.'),
q('Surgery','Dermatology','Pilonidal natal cleft disease','A young adult has recurrent painful swelling at the upper natal cleft. Examination shows midline pits containing hair several centimeters above the anus, with no tract to the anal canal. Which diagnosis is most likely?', 'Pilonidal disease', 'Hair-associated pits in the upper natal cleft with recurrent inflammation are characteristic of pilonidal disease. The location and absence of an anal communication distinguish it from fistula-in-ano; it is not necessarily a congenital spinal defect.', [['Fistula-in-ano as established by an anal tract','No anal communication is demonstrated and the pits lie in the upper cleft.'],['Spina bifida proven by any midline pit','Hair-containing inflammatory natal-cleft pits do not by themselves establish neural tube disease.'],['Rectal carcinoma','The superficial cleft pattern does not identify an intraluminal rectal tumor.']], 'Differentiate hair-associated natal-cleft pits from an anal fistula.'),
q('Surgery','Gastrointestinal','Full thickness rectal prolapse folds','An older patient has a protruding red cylindrical mass during straining. Examination shows concentric circumferential mucosal folds and the entire rectal wall descending through the anus. Which diagnosis fits?', 'Full-thickness rectal prolapse', 'Circumferential concentric folds and full-wall descent support rectal prolapse. Prolapsed hemorrhoidal cushions more often appear as separate radial columns, so the geometry and tissue extent help distinguish two causes of a protruding anorectal mass.', [['Prolapsed hemorrhoids with isolated radial cushions','The concentric full-circumference folds and entire-wall descent favor rectal prolapse.'],['Anal fissure','A linear tear does not produce a cylindrical full-thickness protrusion.'],['Perianal abscess','A localized purulent collection does not create concentric rectal folds.']], 'Use fold orientation and wall extent to distinguish rectal prolapse from hemorrhoidal prolapse.'),
q('Surgery','Gastrointestinal','Pancreatic duct blunt trauma','After a handlebar injury, a patient has persistent epigastric pain. Imaging shows a deep pancreatic transection extending through the expected main duct course. Which anatomic detail most strongly affects the risk of pancreatic leakage?', 'Integrity of the main pancreatic duct', 'A deep parenchymal injury that disrupts the main pancreatic duct can leak enzyme-rich fluid and lead to fistula or collections. Duct status is more clinically informative than serum enzyme elevation alone, which may not quantify the structural injury.', [['Only the superficial skin bruise diameter','Skin bruising does not establish pancreatic duct continuity.'],['Serum lipase as a direct image of an intact duct','An enzyme concentration does not directly demonstrate duct anatomy.'],['The absence of a rib fracture','A pancreatic duct injury can occur without associated rib fracture.']], 'Prioritize duct continuity when assessing consequences of pancreatic transection.'),
q('Surgery','Gastrointestinal','Delayed splenic hemorrhage','A patient had blunt left upper abdominal trauma several days ago. He now develops syncope, hypotension and left shoulder pain. Imaging shows new hemoperitoneum and a splenic subcapsular hematoma. Which complication is most concerning?', 'Delayed splenic bleeding into the peritoneum', 'A splenic injury can bleed after an initially stable interval, especially when a contained hematoma expands or ruptures. Referred left shoulder pain may reflect diaphragmatic irritation; initial improvement does not exclude a later hemorrhagic complication.', [['Simple shoulder strain as the sole cause','A shoulder strain does not explain hypotension and new intraperitoneal blood.'],['Normal delayed healing without bleeding','New hemoperitoneum and collapse indicate a complication rather than ordinary recovery.'],['Isolated renal colic','That does not account for the documented splenic injury and intraperitoneal hemorrhage.']], 'Recognize a delayed hemorrhagic complication after apparently stable splenic trauma.'),
q('Surgery','Gastrointestinal','Seat belt bowel injury evolution','After a car collision, a patient has a lower abdominal seat-belt mark. Initial examination is mild, but several hours later he develops increasing pain, guarding and free intraperitoneal air. Which injury is most concerning?', 'Hollow-viscus injury with perforation', 'Blunt compression or shearing can damage bowel and may become evident after an initially limited examination. New peritonitis and free air suggest perforation; a benign early examination does not permanently exclude evolving abdominal injury.', [['Abdominal wall bruise as the only possible lesion','Progressive guarding and free air indicate deeper injury beyond a skin bruise.'],['Uncomplicated muscle soreness','Muscle pain does not produce intraperitoneal gas and peritoneal irritation.'],['Normal postcollision physiology','The evolving findings indicate a surgical complication rather than normal recovery.']], 'Use evolving examination findings to detect delayed hollow-viscus trauma.'),
q('Surgery','Gastrointestinal','Abdominal trauma free fluid instability','A patient remains hypotensive after major blunt trauma despite initial resuscitation. Bedside ultrasound shows substantial intraperitoneal free fluid, and no competing source explains the shock. Which diagnostic-management priority is appropriate?', 'Urgent surgical hemorrhage assessment without delaying for routine CT', 'Persistent instability with intraperitoneal fluid strongly suggests clinically important abdominal bleeding. CT is useful when physiology permits, but moving an unstable patient for routine detailed imaging can delay hemorrhage control; the constraint is hemodynamic status.', [['Routine CT before any surgical consultation in every patient','Persistent instability makes delay for routine CT potentially harmful.'],['Discharge because ultrasound cannot identify the exact vessel','A precise vessel label is not required to recognize a hemorrhagic emergency.'],['Observe overnight without reassessing circulation','Persistent shock demands immediate intervention and monitoring.']], 'Prioritize hemorrhage control over detailed imaging in unstable trauma.','clinical','prioritization'),
q('Surgery','Dermatology','Full thickness burn sensory loss','After a flame injury, a central burn area is dry, leathery and nonblanching with little pinprick sensation, while surrounding partial-thickness areas are very painful. Which depth best describes the central area?', 'Full-thickness burn', 'Destruction through the dermis can injure sensory endings and produce a leathery poorly sensitive center. Reduced pain therefore does not imply a mild burn; surrounding partial-thickness tissue may remain highly painful because its sensory structures are less completely destroyed.', [['Superficial epidermal burn only','A superficial burn generally remains painful and lacks a leathery insensate center.'],['No significant injury because the center is less painful','Destruction of nerve endings can reduce pain in a deep burn.'],['A simple urticarial wheal','A wheal does not account for thermal destruction and nonblanching eschar.']], 'Interpret reduced central sensation as a possible sign of deep thermal injury.'),
q('Surgery','Respiratory','Inhalation injury progressive airway risk','A patient rescued from an enclosed-space fire has facial burns, soot in the mouth and worsening hoarseness. Oxygen saturation is initially acceptable. Which concern deserves early expert airway assessment?', 'Progressive upper-airway edema', 'Thermal and smoke exposure can produce evolving supraglottic edema before complete obstruction occurs. Worsening voice change and oral soot are concerning despite an initially acceptable saturation; waiting for profound hypoxemia can miss a safer window for controlled airway management.', [['Normal saturation permanently excludes airway injury','Airway edema can progress before major oxygen desaturation develops.'],['Only cosmetic skin damage is possible','Hoarseness and oral soot indicate more than a cosmetic facial burn.'],['All airway assessment should wait until cardiac arrest','Earlier controlled assessment is needed when obstruction may evolve.']], 'Use exposure and voice changes to recognize evolving airway risk before desaturation.'),
q('Surgery','Musculoskeletal','Electrical injury deep tissue damage','A worker contacts a high-voltage line. Skin burns are small, but he develops severe limb pain, swelling and dark urine with urine heme positivity and few erythrocytes. What explains the discrepancy?', 'Deep muscle injury with myoglobin release', 'Electrical energy can damage deep tissues out of proportion to visible entry and exit wounds. Muscle breakdown releases myoglobin, producing heme-positive urine without corresponding red cells; a small skin lesion does not establish a minor injury.', [['Skin area precisely measures all internal electrical damage','Deep current-related injury can substantially exceed the visible skin burn.'],['All dark urine proves intact urinary erythrocytes','Myoglobin can create a positive heme test without many erythrocytes.'],['Normal delayed tanning of the urine','Dark heme-positive urine with muscle pain is not physiologic recovery.']], 'Recognize deep electrical muscle injury despite limited visible skin damage.'),
q('Surgery','Musculoskeletal','Circumferential eschar external constriction','A patient has a circumferential full-thickness forearm burn. As edema increases, distal perfusion worsens beneath a rigid eschar. Which mechanical factor is directly limiting expansion?', 'Noncompliant burned skin encircling the limb', 'A circumferential rigid eschar can externally constrain swelling tissues and compromise distal circulation. This mechanism explains why burn-related release may be needed even though the initial skin appearance seemed stable; it differs from assuming the eschar can expand normally.', [['Normally elastic intact skin increasing its stretch','Full-thickness eschar is noncompliant rather than normally elastic.'],['Isolated superficial itching','Itching does not account for progressive distal perfusion impairment.'],['Normal venous physiology without constriction','A circumferential rigid layer can create a pathologic mechanical restriction.']], 'Identify rigid external eschar as a cause of swelling-related vascular compromise.'),
q('Surgery','Gastrointestinal','Postoperative fascial dehiscence','On postoperative day 7 after laparotomy, a patient feels a pop while coughing and has a sudden increase in pink wound drainage. Examination shows separated fascial edges beneath intact skin staples. What complication has occurred?', 'Fascial wound dehiscence', 'Loss of fascial continuity is a deeper failure than superficial skin separation and may precede evisceration. Sudden serosanguineous drainage and a popping sensation are warning signs; intact skin staples do not demonstrate that the abdominal wall fascia is secure.', [['Normal healing proven by intact skin staples','Skin closure does not establish intact deep fascial closure.'],['Isolated contact dermatitis','Dermatitis does not explain separated fascial edges.'],['A normal subcuticular suture dissolution event','The finding involves structural fascial failure rather than routine suture absorption.']], 'Distinguish deep fascial failure from superficial skin appearance after laparotomy.'),
q('Surgery','Gastrointestinal','Anastomotic leak postoperative sepsis','Five days after bowel resection, a patient develops new tachycardia, fever and worsening abdominal pain. CT shows enteric contrast extravasation beside the anastomosis with a fluid collection. Which process explains the deterioration?', 'Anastomotic leak', 'Escape of enteric contents through a failed anastomotic seal produces local contamination and can cause sepsis. The contrast leak is direct structural evidence, distinguishing this from expected postoperative ileus or a fever attributed to minor atelectasis alone.', [['Expected uncomplicated ileus','Motility slowing does not explain enteric contrast escaping outside the bowel.'],['Normal healing response needing no assessment','New sepsis with extraluminal contrast indicates a complication.'],['Isolated superficial wound itching','A skin symptom does not explain intra-abdominal leakage and systemic illness.']], 'Connect new postoperative sepsis with direct evidence of bowel anastomotic failure.'),
q('Surgery','Gastrointestinal','Chylous postoperative drainage','After retroperitoneal surgery, a drain produces milky fluid that increases after meals. Fluid triglycerides are high and chylomicrons are present. Which structure was most likely disrupted?', 'Lymphatic drainage channel', 'Triglyceride-rich chylomicron-containing fluid represents chyle from intestinal lymphatic transport. A disrupted lymphatic channel can create a postoperative leak; milky appearance alone is less specific, so the lipid analysis distinguishes it from purulent material.', [['An isolated bile duct with pure bile drainage','Bile does not characteristically contain chylomicron-rich milky fluid.'],['A ureter producing normal urine','Urine does not normally have this meal-related chyle composition.'],['A systemic artery leaking only intact blood','Arterial hemorrhage is not a milky triglyceride-rich drainage pattern.']], 'Use meal dependence and chylomicrons to identify a postoperative lymphatic leak.'),
q('Surgery','Gastrointestinal','Enterocutaneous fistula output','After abdominal surgery, a wound begins draining fluid containing visible intestinal contents. Contrast imaging demonstrates a tract from a small-bowel loop to the skin. What diagnosis is established?', 'Enterocutaneous fistula', 'A demonstrated connection between bowel lumen and skin explains enteric wound drainage. Output can cause important fluid and nutritional losses, so recognizing the tract has implications beyond treating the wound as a superficial infection.', [['Isolated superficial stitch abscess','A stitch abscess does not establish a contrast-confirmed bowel-to-skin connection.'],['Chylous leak without bowel communication','Chyle is lymphatic fluid and does not require a tract from the bowel lumen.'],['Normal granulation drainage','Normal wound exudate does not contain intestinal contents through a demonstrated tract.']], 'Identify a bowel-to-skin communication and its fluid-loss implications.'),
q('Surgery','Respiratory','Bilateral recurrent laryngeal injury','Following thyroid surgery, a patient develops stridor. Laryngoscopy shows both vocal folds fixed near the midline with poor abduction. Which injury best explains the airway narrowing?', 'Bilateral recurrent laryngeal nerve dysfunction', 'The recurrent laryngeal nerves supply most intrinsic laryngeal muscles, including the sole vocal-fold abductors. Bilateral dysfunction can leave the folds near the midline and narrow the airway; unilateral injury more commonly presents primarily with voice change.', [['Isolated unilateral external superior laryngeal injury','That affects pitch control more than producing bilateral failed abduction.'],['Isolated hypoglossal nerve injury','Tongue motor loss does not directly fix both vocal folds near the midline.'],['Normal postoperative vocal-fold motion','Fixed near-midline folds with stridor indicate abnormal airway mechanics.']], 'Connect bilateral failed vocal-fold abduction after thyroid surgery with recurrent nerve dysfunction.'),
q('Surgery','Respiratory','Postthyroidectomy neck hematoma','Two hours after thyroidectomy, a patient develops rapidly increasing neck swelling, tightness and breathing difficulty. The surgical dressing is tense. Which complication must be considered immediately?', 'Expanding cervical hematoma threatening the airway', 'Postoperative bleeding within the confined neck can compress the airway and worsen rapidly. The expanding swelling distinguishes this from isolated transient hoarseness; respiratory compromise requires an immediate surgical response rather than waiting for a later routine imaging appointment.', [['Routine mild incisional discomfort','Rapid expansion and breathing difficulty are not routine postoperative soreness.'],['Delayed hypothyroidism as the cause of sudden swelling','Hormone deficiency does not explain an acutely tense expanding surgical wound.'],['Normal scar formation within two hours','Scar maturation does not produce immediate expanding airway-threatening neck swelling.']], 'Recognize airway threat from rapidly expanding postoperative cervical bleeding.'),
q('Surgery','Nervous System','Parotid surgery facial motor deficit','After parotid tumor removal, a patient cannot close the ipsilateral eye and has a drooping mouth corner, while facial sensation remains intact. Which injured structure best explains the deficit?', 'Facial nerve motor branches', 'The facial nerve courses through the parotid gland and supplies muscles of facial expression. Eye closure and lower facial weakness with preserved sensation indicate motor facial dysfunction rather than a trigeminal sensory lesion.', [['Trigeminal sensory branches only','A sensory lesion would not directly explain weakness of eye closure and mouth movement.'],['Hypoglossal nerve','That nerve controls tongue movement rather than facial expression.'],['Greater occipital nerve','A posterior scalp sensory nerve does not supply these facial muscles.']], 'Localize a postsurgical parotid motor deficit using movement and preserved sensation.'),
q('Surgery','Nervous System','Carotid surgery hypoglossal deficit','After carotid endarterectomy, a patient has new tongue weakness. On protrusion the tongue deviates toward the operated side; facial movement and vocal-fold motion are preserved. Which nerve was most likely injured?', 'Hypoglossal nerve', 'The hypoglossal nerve supplies tongue muscles and lies near the carotid operative field. A unilateral lower motor neuron injury causes protrusion toward the weak side; preserved facial and laryngeal function helps distinguish nearby cranial nerve alternatives.', [['Facial nerve','Facial injury affects expression rather than isolated tongue protrusion.'],['Recurrent laryngeal nerve','That more directly affects vocal-fold movement, which is preserved.'],['Optic nerve','A visual pathway lesion does not cause a unilateral tongue motor deficit.']], 'Use isolated ipsilateral tongue deviation to identify a cranial nerve injury after carotid surgery.'),
q('Surgery','Renal','Penile fracture tunical disruption','During intercourse, a patient hears a snap, has immediate penile pain and detumescence, then develops swelling and ecchymosis. Which structure is most likely torn?', 'Tunica albuginea of the corpus cavernosum', 'An acute snap with immediate loss of erection and expanding hematoma is characteristic of penile fracture, meaning rupture of the cavernosal tunica rather than a bone injury. Associated urethral injury must also be considered when urinary warning signs are present.', [['A nonexistent penile long bone','Human penile fracture describes fibrous tunical rupture rather than a bone fracture.'],['An isolated superficial hair follicle','A follicular injury does not explain the sudden snap and immediate detumescence.'],['The epididymal head','An epididymal lesion is scrotal and does not explain cavernosal hematoma.']], 'Identify the fibrous structure disrupted in the classic acute penile injury pattern.'),
q('Surgery','Renal','Ischemic priapism cavernosal blood','A patient has a painful rigid erection persisting for six hours without stimulation. Cavernosal blood is dark, hypoxic, hypercarbic and acidotic. Which type of priapism is present?', 'Ischemic low-flow priapism', 'Painful rigid corpora with stagnant hypoxic acidotic blood indicate impaired venous outflow and ischemia. This differs from often less painful high-flow priapism after arterial trauma; duration matters because prolonged ischemia can damage erectile tissue.', [['Nonischemic high-flow priapism','High-flow arterial physiology does not fit markedly hypoxic acidotic cavernosal blood.'],['Normal brief nocturnal erection','A persistent painful six-hour event with ischemic blood is not normal physiology.'],['Simple painless hydrocele','A scrotal fluid collection does not explain persistent rigid corporal tissue.']], 'Classify priapism using pain, rigidity and cavernosal gas physiology.'),
q('Surgery','Renal','Solid intratesticular mass assessment','A young adult has a new painless firm testicular lump. Ultrasound confirms a solid intratesticular lesion rather than a cyst outside the testis. Which interpretation is most appropriate?', 'Testicular malignancy must be considered', 'A solid lesion within testicular parenchyma warrants evaluation for malignancy even when painless. Many benign scrotal conditions are extratesticular, so accurately identifying the anatomic compartment is more informative than reassurance from the absence of pain.', [['Painlessness excludes testicular cancer','Testicular tumors often present without pain.'],['Every solid intratesticular lesion is definitively malignant','The finding raises concern but histologic classification is not established by location alone.'],['A normal epididymal cyst is demonstrated','The lesion is explicitly intratesticular and solid rather than epididymal and cystic.']], 'Use solid intratesticular location as a malignancy concern without equating concern with proof.'),
q('Surgery','Renal','Spermatocele epididymal cyst','A patient has a painless mobile scrotal lump above and behind the testis. Ultrasound shows a cyst arising from the epididymal head with a normal separate testis. Which diagnosis is most consistent?', 'Spermatocele', 'A benign cystic lesion arising from the epididymal head is typical of a spermatocele. Separating the cyst from the normal testis helps distinguish it from a solid intratesticular tumor; anatomic localization is therefore central to the interpretation.', [['Solid intratesticular seminoma as demonstrated','The lesion is cystic and epididymal rather than solid and within testicular tissue.'],['Acute torsion with ischemia','There is no acute pain or perfusion abnormality and the lesion is a discrete cyst.'],['Incarcerated bowel hernia','No bowel-containing groin communication is described.']], 'Identify an epididymal head cyst separately from a testicular parenchymal lesion.'),
q('Surgery','Cardiovascular','Venous stasis ulcer distribution','A patient with chronic leg swelling has a shallow irregular ulcer near the medial malleolus. Surrounding skin has brown pigmentation and pulses are palpable. Which underlying process best explains the ulcer?', 'Chronic venous hypertension', 'Venous hypertension causes edema, inflammatory skin changes and gaiter-region ulceration, often near the medial malleolus. Preserved pulses and pigmentation support the venous pattern, though mixed arterial disease can coexist and must be assessed before compression decisions.', [['Isolated severe arterial insufficiency as proven by palpable pulses','The distribution, edema and pigmentation favor venous disease rather than proving arterial occlusion.'],['A primary pressure injury over the heel','The ulcer is in a venous gaiter distribution rather than a focal heel pressure point.'],['Acute allergic urticaria','Transient wheals do not explain chronic edema and ulceration.']], 'Integrate ulcer site, surrounding skin and pulses to identify venous hypertension.'),
q('Surgery','Cardiovascular','Arterial ischemic toe ulcer','A patient has a painful sharply demarcated toe ulcer, a cool foot, dependent rubor and weak pedal pulses. Pain worsens with elevation. Which mechanism best fits?', 'Insufficient arterial perfusion', 'Distal painful punched-out ulcers with coolness and reduced pulses suggest arterial ischemia. Elevation further reduces perfusion pressure, worsening pain; the pattern differs from the edematous pigmented medial-ankle presentation of chronic venous disease.', [['Uncomplicated venous hypertension alone','The cool weakly perfused foot and distal ischemic ulcer favor arterial insufficiency.'],['Normal skin aging','Painful tissue loss with perfusion abnormalities is not a normal aging change.'],['Isolated painless neuropathic callus','Neuropathic ulcers more often occur at pressure points and need not have weak pulses or ischemic pain.']], 'Distinguish distal ischemic tissue loss from venous and purely neuropathic ulcers.'),
q('Surgery','Cardiovascular','Popliteal aneurysm thrombosis','An older patient has a pulsatile mass behind the knee and develops new distal ischemic symptoms. Ultrasound shows a dilated popliteal artery containing mural thrombus. Which complication most directly threatens the foot?', 'Thrombosis or distal embolization from the aneurysm', 'A popliteal aneurysm can harbor thrombus that occludes local flow or embolizes to distal vessels. Limb ischemia may therefore arise from an enlarged artery rather than only a fixed stenotic plaque; the pulsatile mass localizes the source.', [['A benign synovial cyst with no vascular involvement','A Baker cyst is not a thrombus-containing dilated artery.'],['Isolated nerve compression as the sole explanation for absent perfusion','Nerve compression does not account for the demonstrated arterial thrombus and ischemia.'],['Improved distal flow guaranteed by arterial dilation','An aneurysm can impair perfusion through thrombosis despite its increased diameter.']], 'Recognize thromboembolism as a limb-threatening consequence of a popliteal aneurysm.'),
q('Surgery','Gastrointestinal','Appendicitis ultrasound confirmation','An adolescent has fever, focal right lower quadrant tenderness and neutrophilia. Graded compression ultrasound identifies a blind-ending noncompressible tubular structure arising from the cecum with surrounding inflammatory change. Which diagnosis is supported?', 'Acute appendicitis', 'A blind-ending inflamed noncompressible appendiceal structure with compatible symptoms supports appendicitis. The imaging objective differs from merely explaining pain migration; no single symptom alone is definitive, and the entire clinical and imaging pattern should be integrated.', [['Uncomplicated functional abdominal pain','The focal inflammatory imaging and systemic findings indicate an organic process.'],['Normal compressible appendix','The structure is explicitly noncompressible with surrounding inflammatory change.'],['Isolated ovarian follicular cyst','The lesion arises from the cecum rather than the ovary.']], 'Integrate appendiceal ultrasound morphology with a focal inflammatory presentation.','appendicitis'),
q('Psychiatry','Behavioral Health','Postpartum psychosis safety priority','One week after childbirth, a patient has slept very little and believes the infant is possessed. She hears commanding voices and cannot reliably participate in a safety plan. Which action is most appropriate?', 'Immediate psychiatric emergency evaluation with protection of mother and infant', 'New postpartum delusions, hallucinations and severe disorganization indicate a psychiatric emergency. Immediate assessment and a safe supervised setting are needed; ordinary postpartum emotional lability does not explain loss of reality testing or justify delayed follow-up.', [['Routine reassurance with a visit in two months','Psychotic symptoms and an unreliable safety plan require immediate assessment.'],['Leave her alone to recover sleep while solely caring for the infant','The described loss of reality testing creates an unsafe unsupervised situation.'],['Classify the symptoms as normal baby blues','Baby blues do not include delusions and command hallucinations.']], 'Prioritize immediate safety when postpartum symptoms include impaired reality testing.','perinatal','prioritization'),
q('Psychiatry','Behavioral Health','Postpartum depression versus blues','Four weeks after delivery, a patient has persistent depressed mood, anhedonia, guilt and impaired daily functioning. Symptoms have lasted three weeks rather than improving after a few days. Which interpretation is most appropriate?', 'Assess for a postpartum major depressive episode', 'Persistent depressive symptoms beyond the usual brief postpartum blues, especially anhedonia and functional impairment, warrant evaluation for a depressive episode. Assessment must include safety and other causes; childbirth does not make sustained severe symptoms a normal adjustment by definition.', [['Normal baby blues requiring no assessment regardless of severity','Duration and functional impairment extend beyond a typical transient blues pattern.'],['Postpartum psychosis is proven without psychotic symptoms','No hallucinations, delusions or loss of reality testing are supplied.'],['Depression cannot begin after delivery','The perinatal period is a recognized time for depressive illness.']], 'Distinguish persistent impairing depression from transient postpartum mood lability.','perinatal'),
q('Psychiatry','Behavioral Health','Mania severity and psychosis','An adult has nine days of markedly increased energy, little need for sleep, pressured speech and reckless spending. He requires hospitalization and has grandiose delusions. Substance and medical causes are excluded. Which episode is most consistent?', 'Manic episode', 'Sustained elevated energy with characteristic symptoms, marked impairment and psychosis fits mania. Hypomania does not include psychosis or this degree of functional disruption; the duration and exclusion of other causes strengthen the episode classification.', [['Hypomanic episode despite psychosis and hospitalization','Psychotic features and severe impairment are incompatible with a hypomanic classification.'],['Normal productivity during a busy week','Reduced sleep need, delusions and dangerous impairment exceed normal productivity.'],['An isolated panic attack','Panic is brief and does not explain a sustained multi-day activation syndrome.']], 'Use duration, impairment and psychosis to distinguish mania from hypomania.','bipolar'),
q('Psychiatry','Behavioral Health','Obsessions ego dystonic insight','A patient spends hours checking the stove because of unwanted intrusive fears of causing a fire. She recognizes the rituals are excessive and feels distressed by them, but cannot easily stop. Which feature distinguishes an obsession from a fixed delusion here?', 'The thoughts are intrusive and recognized as unreasonable', 'Obsessive fears are typically unwanted and may be accompanied by insight and repetitive neutralizing rituals. The stated recognition contrasts with a fixed delusional conviction, although insight varies across patients and its presence alone does not describe the whole disorder.', [['Any repeated thought proves psychosis','Repetitive unwanted fears with insight can occur without a psychotic disorder.'],['Compulsions are always pleasurable hobbies','These time-consuming rituals are distress-driven rather than ordinary enjoyable activities.'],['Intact insight means the symptoms cannot be clinically significant','Severe impairment can occur even when a patient recognizes excessiveness.']], 'Differentiate an intrusive obsession with insight from fixed delusional conviction.','ocd'),
q('Psychiatry','Behavioral Health','Anorexia medical instability priority','A patient restricting food because of intense fear of weight gain has marked weight loss, pulse 38/min, hypotension and recurrent fainting. Which immediate priority best fits the presentation?', 'Urgent assessment and stabilization of medical instability', 'Eating disorders can cause dangerous cardiovascular and metabolic complications. Severe bradycardia, hypotension and syncope require urgent medical evaluation alongside psychiatric care; focusing only on body-image discussion can delay treatment of life-threatening physiologic compromise.', [['Routine counseling alone before any medical assessment','The hemodynamic abnormalities require urgent medical evaluation.'],['Reassure that all slow pulses reflect athletic conditioning','Syncope, hypotension and malnutrition argue against benign conditioning alone.'],['Treat the illness as solely a matter of food preference','Restrictive eating with major physiologic consequences is a serious disorder.']], 'Prioritize physical instability while addressing an eating disorder.','eating','prioritization'),
q('Ethics','Behavioral Health','Current patient sexual boundary','A current patient asks her treating physician to begin a sexual relationship and states that she freely consents. The physician is responsible for ongoing treatment. Which response best follows professional ethics?', 'Decline and maintain appropriate professional boundaries', 'A sexual relationship with a current patient violates the clinical boundary despite expressed consent. The professional role creates vulnerability and power asymmetry; the physician should preserve appropriate care while addressing the request respectfully.', [['Proceed because verbal consent removes every professional concern','Consent does not remove the treating clinician professional boundary.'],['Exchange preferential treatment for the relationship','That introduces exploitation into an already inappropriate relationship.'],['Publicly disclose the request to shame the patient','Humiliation and unnecessary disclosure violate respect and confidentiality.']], 'Apply the professional boundary prohibiting sexual relationships with current patients.','ethics','application'),
q('Ethics','Behavioral Health','Financial referral conflict','A physician recommends a diagnostic center in which she has a financial interest. An equally suitable independent center is available and the patient asks about alternatives. Which approach best preserves ethical decision making?', 'Disclose and manage the conflict while presenting clinically appropriate alternatives', 'A financial interest can bias recommendations even when the test is reasonable. Recognizing, disclosing and managing the conflict supports independent clinical judgment; disclosure alone does not make an unnecessary referral appropriate or remove the duty to explain alternatives.', [['Conceal ownership because the test might still help','Potential benefit does not eliminate the need to manage a material conflict.'],['Order extra testing to maximize the physician return','Personal financial gain must not drive the clinical recommendation.'],['Assume disclosure makes every referral ethical','The referral must still be clinically justified and the conflict properly managed.']], 'Recognize that disclosure and independent clinical justification are both necessary in a financial conflict.','ethics'),
q('Ethics','Behavioral Health','Impaired colleague immediate patient safety','Before an operation, a physician observes that the assigned surgeon smells of alcohol, is unsteady and has slurred speech. The surgeon insists on proceeding. Which immediate response is most appropriate?', 'Prevent unsafe practice and activate appropriate institutional assistance', 'Observed possible impairment with imminent patient care creates a duty to protect patients promptly. The cause can be assessed through appropriate channels, but waiting for an injury or treating the issue solely as a private disagreement fails the immediate safety obligation.', [['Wait for a surgical complication before responding','A credible imminent safety threat should be addressed before harm occurs.'],['Ignore the findings to preserve collegial loyalty','Collegiality does not supersede patient safety.'],['Announce an unverified diagnosis to all patients publicly','An appropriate safety process protects patients without unnecessary public speculation.']], 'Prioritize immediate patient protection while using proper channels for suspected clinician impairment.','ethics','prioritization'),
q('Ethics','Behavioral Health','Fair resource allocation social status','Two patients have the same urgent need and expected benefit from one available treatment slot. One offers a large donation to secure priority. No established allocation policy supports financial preference. Which criterion is inappropriate?', 'Ability to provide a personal financial reward', 'Allocation should follow fair clinically relevant criteria rather than reward for the clinician or institution. A proposed donation is not a medical difference between otherwise similarly situated patients; a transparent policy is needed to resolve a genuine tie.', [['A transparent equitable policy for similarly situated patients','A consistently applied fair policy is appropriate when clinical priority is tied.'],['Clinically relevant urgency when it differs','A difference in urgency can appropriately influence allocation.'],['Expected clinical benefit when supported by evidence','Potential benefit can be a relevant criterion in a fair allocation policy.']], 'Reject personal financial reward as an allocation criterion while preserving relevant clinical criteria.','ethics','application'),
q('Ethics','Behavioral Health','Accurate clinical documentation','A clinician realizes a late entry is needed to describe care provided yesterday. A colleague suggests altering the original time stamp so the record appears contemporaneous. Which approach best maintains record integrity?', 'Make an accurate transparently identified late entry', 'Medical records should accurately reflect care and documentation timing. A dated identified late entry can add omitted information without falsely representing when it was recorded; backdating undermines integrity even when the underlying clinical event actually occurred.', [['Backdate the entry because the clinical event was real','Truth about the event does not justify falsely representing documentation timing.'],['Invent examination findings to make the note complete','Unobserved findings must not be fabricated in a clinical record.'],['Delete all earlier documentation without an audit trail','Destructive concealed alteration undermines the accuracy and traceability of the record.']], 'Preserve truthfulness about both clinical events and documentation timing.','ethics','application'),
];
